cats={c['id']:c for c in CATEGORIES}
count=defaultdict(int)
old=json.loads((ROOT/'data/catalog.json').read_text(encoding='utf-8'))
old_by_name={e['name']:e for e in old['entries']}
all_entries=[]
for raw in CATALOG:
    e=dict(raw);cat=e['category'];count[cat]+=1
    e['id']=PREFIX[list(cats).index(cat)]+f'{count[cat]:03}'
    prior=old_by_name.get(e['name'])
    if prior and prior.get('visual'):
        e['visual']=prior['visual']
    all_entries.append(e)
assert len({e['name'] for e in all_entries})==len(all_entries)

